function leave_balance($empId)
{
    $ent = (float)setting('leave_entitlement', 30);
    $used = (float)val("SELECT COALESCE(SUM(days),0) FROM leave_requests WHERE employee_id=? AND status='Approved' AND leave_type='Annual Leave' AND date_from>=? AND archived=0", [$empId, date('Y-01-01')]);
    return $ent - $used;
}
/** Payroll inputs come from HRM: salary, approved overtime, unpaid leave and absences. */
function payroll_calc($empId, $period)
{
    $e = row('SELECT * FROM employees WHERE id=?', [$empId]);
    $start = $period . '-01';
    $end = date('Y-m-t', strtotime($start));
    $ot = (float)val("SELECT COALESCE(SUM(hours*rate),0) FROM overtime WHERE employee_id=? AND status='Approved' AND ot_date BETWEEN ? AND ? AND archived=0", [$empId, $start, $end]);
    $unpaid = (float)val("SELECT COALESCE(SUM(days),0) FROM leave_requests WHERE employee_id=? AND status='Approved' AND leave_type='Unpaid Leave' AND date_from BETWEEN ? AND ? AND archived=0", [$empId, $start, $end]);
    $absent = (int)val("SELECT COUNT(*) FROM attendance WHERE employee_id=? AND status='Absent' AND att_date BETWEEN ? AND ? AND archived=0", [$empId, $start, $end]);
    $daily = ((float)$e['basic_salary']) / 30;
    return ['basic' => (float)$e['basic_salary'], 'allowances' => (float)$e['allowances'], 'overtime_amount' => round($ot, 2), 'unpaid_days' => $unpaid + $absent, 'absence_deduction' => round($daily * ($unpaid + $absent), 2)];
}
function payslip($r)
{
    $e = row('SELECT * FROM employees WHERE id=?', [$r['employee_id']]);
    $abs = round(((float)$r['basic'] / 30) * (float)$r['unpaid_days'], 2);
    card_open(icon('file-text', 17) . ' Payslip · ' . e($r['period']), '<button class="btn ghost sm no-print" data-print>' . icon('printer', 14) . ' Print</button>', 'payslip');
    echo '<p><b>' . e(setting('company_name')) . '</b><br><span class="muted small">' . e($e['name'] ?? '') . ' · ' . e($e['designation'] ?? '') . ' · ' . e($e['department'] ?? '') . '</span></p><table class="table compact"><tbody>'
        . '<tr><td>Basic salary</td><td class="num">' . money($r['basic']) . '</td></tr><tr><td>Allowances</td><td class="num">' . money($r['allowances']) . '</td></tr><tr><td>Overtime (approved)</td><td class="num">' . money($r['overtime_amount']) . '</td></tr>'
        . '<tr><td>Unpaid leave / absence (' . num($r['unpaid_days']) . ' days)</td><td class="num">− ' . money($abs) . '</td></tr><tr><td>Other deductions</td><td class="num">− ' . money($r['deductions']) . '</td></tr></tbody><tfoot><tr><td>Net pay</td><td class="num">' . money($r['net']) . '</td></tr></tfoot></table>';
    card_close();
}

