ent('stock_movements', ['label' => 'Stock Movements', 'one' => 'Stock movement', 'title' => 'kind', 'icon' => 'activity', 'immutable' => true,
    'fields' => ['item_id' => ['Item', 'ref:inventory_items', 'req'], 'kind' => ['Movement', 'enum:In|Out|Adjustment', 'req'], 'qty' => ['Quantity', 'number', 'req'], 'move_date' => ['Date', 'date', 'default' => date('Y-m-d')], 'note' => ['Note', 'text']],
    'list' => ['item_id', 'kind', 'qty', 'move_date', 'note'],
    'before_save' => function (&$d, $old) { $q = (float)val('SELECT qty FROM inventory_items WHERE id=?', [$d['item_id']]); if ($d['kind'] === 'Out' && $d['qty'] > $q) return 'Not enough stock (' . num($q) . ' on hand).'; return null; },
    'after_save' => function ($id, $d, $old) { $delta = $d['kind'] === 'Out' ? -$d['qty'] : $d['qty']; if ($d['kind'] === 'Adjustment') q('UPDATE inventory_items SET qty=? WHERE id=?', [$d['qty'], $d['item_id']]); else q('UPDATE inventory_items SET qty=qty+? WHERE id=?', [$delta, $d['item_id']]); }]);
ent('stock_transfers', ['label' => 'Stock Transfers', 'one' => 'Stock transfer', 'prefix' => 'TRF', 'icon' => 'truck', 'immutable' => true,
    'fields' => ['item_id' => ['Item (source)', 'ref:inventory_items', 'req'], 'to_warehouse_id' => ['To warehouse', 'ref:warehouses', 'req', 'norel' => true], 'qty' => ['Quantity', 'number', 'req'], 'transfer_date' => ['Date', 'date', 'default' => date('Y-m-d')], 'note' => ['Note', 'text']],
    'list' => ['ref_no', 'item_id', 'to_warehouse_id', 'qty', 'transfer_date'],
    'before_save' => function (&$d, $old) { $it = row('SELECT * FROM inventory_items WHERE id=?', [$d['item_id']]); if (!$it) return 'Item not found.'; if ((int)$it['warehouse_id'] === (int)$d['to_warehouse_id']) return 'Choose a different warehouse.'; if ($d['qty'] > $it['qty']) return 'Not enough stock to transfer.'; return null; },
    'after_save' => function ($id, $d, $old) { $it = row('SELECT * FROM inventory_items WHERE id=?', [$d['item_id']]); q('UPDATE inventory_items SET qty=qty-? WHERE id=?', [$d['qty'], $it['id']]); $t = val('SELECT id FROM inventory_items WHERE sku=? AND warehouse_id=? AND archived=0', [$it['sku'], $d['to_warehouse_id']]); if ($t) q('UPDATE inventory_items SET qty=qty+? WHERE id=?', [$d['qty'], $t]); else ins('inventory_items', ['item' => $it['item'], 'sku' => $it['sku'], 'warehouse_id' => $d['to_warehouse_id'], 'qty' => $d['qty'], 'unit' => $it['unit'], 'reorder_level' => $it['reorder_level'], 'created_at' => now(), 'archived' => 0]); }]);
